// globalSetup.js
import { exec } from "child_process";

const globalSetup = async (config) => {
  const server = await exec(`${pathToExecutable}`);
  config.server = server;

  // add event handlers if necessary, e.g.
  // server.stdout.on("data", (data) => {})

  // add check for server started if necessary
}

// globalTeardown.js
const globalTeardown = async (config) => {
  if (config.server) await config.server.kill();
};
